export function coverForTrack(track){
  if(!track || typeof track!=="object")return "";
  const key=String(track.objectKey||"");
  if(key && !Object.hasOwn(artwork.byObjectKey,key) && !/^music\/(a1|a2|b1|b2|c1|c2)\/day-\d{2}\/[^/\\]+\.mp3$/i.test(key))return "";
  const name=artwork.byObjectKey[key] || artwork.byTrackId[String(track.id||"")] || artwork.default;
  return paths[name];
}
